import json
from datetime import datetime, timezone, timedelta
import pytz

def parse_iso8601_z(dt):
    # Handle Zulu or offset
    try:
        if dt.endswith("Z"):  # simple Zulu
            return datetime.strptime(dt, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
        else:
            return datetime.fromisoformat(dt)
    except Exception as e:
        raise ValueError(f"Invalid datetime: {dt}: {e}")

with open("ledger.json") as f:
    data = json.load(f)

# Step 1: collapse rows by event_id, keeping highest revision
collapse = {}
for row in data:
    eid = row["event_id"]
    rev = row.get("revision", 1)
    if (eid not in collapse) or (rev > collapse[eid]["revision"]):
        collapse[eid] = row

# Step 2: filter to customer_id == 'account-202'
rows = [r for r in collapse.values() if r["customer_id"] == "account-202"]

# Step 3: status == settled only
rows = [r for r in rows if r["status"] == "settled"]

# Step 4: restrict to May 2026 (UTC boundaries)
may_start = datetime(2026,5,1,0,0,0,tzinfo=timezone.utc)
jun_start = datetime(2026,6,1,0,0,0,tzinfo=timezone.utc)
def in_may_utc(r):
    dt = parse_iso8601_z(r["occurred_at"])
    return (may_start <= dt) and (dt < jun_start)
rows = [r for r in rows if in_may_utc(r)]

# Step 5-6: sum captures, subtract refunds, per currency
result = {}
included_event_ids = []
for r in rows:
    eid = r["event_id"]
    included_event_ids.append(eid)
    ccy = r["currency"]
    amt = r["amount_minor"]
